SELECT toString(person_id) AS person, toJSONString(groupArray(tuple(toString(timestamp), event, toString(uuid), coalesce(toString(properties.job_id), toString(properties.jobId), ''), coalesce(toString(properties.editor_id), toString(properties.editorId), ''), coalesce(toString(properties.sessionId), toString(properties.$session_id), ''), coalesce(toString(properties.source), ''), coalesce(toString(properties.blocked_reason), toString(properties.reason), ''), coalesce(toString(properties.action), '')))) AS history FROM events WHERE timestamp >= '2026-09-01' AND timestamp < '2026-10-16' AND (properties.environment = 'production' OR properties.environment IS NULL) AND event IN ('signup_completed','login_succeeded','product_home_viewed','gte_session_started','transcription_started','transcription_succeeded','transcription_failed','transcription_imported_to_editor','gte_editor_imported','gte_editor_action','gte_editor_saved','gte_practice_started','pricing_viewed','pricing_billing_selected','transcription_submission_blocked','checkout_started','checkout_client_failed','checkout_cancelled','subscription_started','subscription_ended','premium_prompt_viewed','premium_prompt_dismissed','inactive_signup_reminder_sent','tab_return_reminder_sent','reminder_email_unsubscribed') GROUP BY person_id HAVING countIf(event = 'signup_completed') > 0 OR countIf(event = 'subscription_started') > 0 ORDER BY person LIMIT 500
